def get_historical_k_data(code, start_date, end_date, frequency="d", adjust_flag="3", fields=None, **_extra):
    import json, os, datetime
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0362000" if __import__("os").path.isdir("./environment_mix/0362000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = datetime.datetime.utcnow()
    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_ymd(s, field):
        if not isinstance(s, str):
            return None, _err("VALIDATION_ERROR", f"{field} must be a string in YYYY-MM-DD format", field=field)
        try:
            return datetime.datetime.strptime(s, "%Y-%m-%d").date(), None
        except ValueError:
            return None, _err("VALIDATION_ERROR", f"{field} must be in YYYY-MM-DD format", field=field)

    def _parse_dt_any(v):
        if v is None:
            return None
        if isinstance(v, (int, float, bool)):
            return None
        if isinstance(v, datetime.datetime):
            return v
        if isinstance(v, datetime.date):
            return datetime.datetime(v.year, v.month, v.day)
        if isinstance(v, str):
            s = v.strip()
            if not s:
                return None
            if s.endswith("Z"):
                s = s[:-1]
            for fmt in ("%Y-%m-%dT%H:%M:%S", "%Y-%m-%d %H:%M:%S", "%Y-%m-%d"):
                try:
                    return datetime.datetime.strptime(s, fmt)
                except ValueError:
                    continue
        return None

    def _audit(status, error_code=None):
        try:
            logs = _load("request_logs.json")
            if not isinstance(logs, list):
                logs = []
        except Exception:
            logs = []
        latency_ms = int((datetime.datetime.utcnow() - t0).total_seconds() * 1000)
        logs.append({
            "id": f"req_{datetime.datetime.utcnow().strftime('%Y%m%d%H%M%S%f')}",
            "endpoint": "get_historical_k_data",
            "status": status,
            "error_code": error_code,
            "latency_ms": latency_ms,
            "timestamp": _now_iso(),
        })
        try:
            _save("request_logs.json", logs)
        except Exception:
            pass

    # Validation
    if not isinstance(code, str) or not code.strip():
        _audit("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "code must be a non-empty string", field="code")
    if frequency is None:
        frequency = "d"
    if adjust_flag is None:
        adjust_flag = "3"
    if not isinstance(frequency, str) or frequency not in ("d",):
        _audit("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "frequency must be one of ('d')", field="frequency")
    if not isinstance(adjust_flag, str) or not adjust_flag:
        _audit("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "adjust_flag must be a non-empty string", field="adjust_flag")
    if fields is not None:
        if not isinstance(fields, list) or any((not isinstance(x, str) or not x.strip()) for x in fields):
            _audit("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "fields must be an array of non-empty strings or null", field="fields")

    sd, e = _parse_ymd(start_date, "start_date")
    if e:
        _audit("error", "VALIDATION_ERROR")
        return e
    ed, e = _parse_ymd(end_date, "end_date")
    if e:
        _audit("error", "VALIDATION_ERROR")
        return e
    if sd > ed:
        _audit("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "start_date must be <= end_date", field="start_date")

    # Resolve security by bs_code (must exist)
    securities = _load("securities.json")
    if not isinstance(securities, list):
        securities = []
    sec = None
    for r in securities:
        if isinstance(r, dict) and r.get("bs_code") == code:
            sec = r
            break
    if not sec:
        _audit("error", "NOT_FOUND")
        return _err("NOT_FOUND", "security code not found", field="code", code_value=code)

    sec_id = sec.get("id")
    ts = _load("security_time_series.json")
    if not isinstance(ts, list):
        ts = []

    rows = []
    for r in ts:
        if not isinstance(r, dict):
            continue
        if r.get("status") != "active":
            continue
        if r.get("series_type") != "kline":
            continue
        if r.get("security_id") != sec_id:
            continue
        if r.get("frequency") != frequency:
            continue
        if r.get("adjust_flag") != adjust_flag:
            continue
        td = _parse_dt_any(r.get("trade_date"))
        if td is None:
            continue
        d = td.date()
        if sd <= d <= ed:
            rows.append(r)

    # sort by trade_date asc
    def _td_key(r):
        td = _parse_dt_any(r.get("trade_date"))
        return td or datetime.datetime(1970, 1, 1)
    rows.sort(key=_td_key)

    # projection
    kline_all_cols = [
        "trade_date", "open", "high", "low", "close", "volume", "amount", "turn", "pct_chg",
        "frequency", "adjust_flag"
    ]
    out = []
    want = None
    if fields is not None and len(fields) > 0:
        want = [f.strip() for f in fields if f.strip()]
        # always include trade_date
        if "trade_date" not in want:
            want = ["trade_date"] + want

    for r in rows:
        if want is None:
            obj = {k: r.get(k) for k in kline_all_cols if k in r or k == "trade_date"}
            # ensure trade_date exists
            if "trade_date" not in obj:
                obj["trade_date"] = r.get("trade_date")
        else:
            obj = {k: r.get(k) for k in want}
        out.append(obj)

    resp = {
        "code": code,
        "security_id": sec_id,
        "frequency": frequency,
        "adjust_flag": adjust_flag,
        "start_date": start_date,
        "end_date": end_date,
        "data": out,
        "meta": {"count": len(out)}
    }
    _audit("ok", None)
    return resp

