def get_profit_data(code, year, quarter, **_extra):
    import json, os, datetime
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0362000" if __import__("os").path.isdir("./environment_mix/0362000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    _t0 = datetime.datetime.utcnow()

    def _log(status, error=None, **meta):
        try:
            logs = _load("request_logs.json")
            if not isinstance(logs, list):
                logs = []
            now = datetime.datetime.utcnow()
            latency_ms = int((now - _t0).total_seconds() * 1000)
            row = {
                "id": f"req_{now.strftime('%Y%m%d%H%M%S%f')}",
                "endpoint": "get_profit_data",
                "status": status,
                "latency_ms": latency_ms,
                "timestamp": now.isoformat() + "Z",
                "params": {"code": code, "year": year, "quarter": quarter},
            }
            if meta:
                row["meta"] = meta
            if error:
                row["error"] = error
            logs.append(row)
            _save("request_logs.json", logs)
        except Exception:
            pass

    def _md_table(rows):
        if not rows:
            return ""
        cols = []
        for r in rows:
            for k in r.keys():
                if k not in cols:
                    cols.append(k)
        cols = [c for c in cols if c not in ("id", "status", "created_at", "updated_at")]
        preferred = ["dataset_type", "security_id", "year", "quarter"]
        cols_sorted = [c for c in preferred if c in cols] + [c for c in cols if c not in preferred]
        def _fmt(v):
            if v is None:
                return ""
            if isinstance(v, (dict, list)):
                return json.dumps(v, ensure_ascii=False)
            return str(v)
        header = "| " + " | ".join(cols_sorted) + " |"
        sep = "| " + " | ".join(["---"] * len(cols_sorted)) + " |"
        body = []
        for r in rows:
            body.append("| " + " | ".join(_fmt(r.get(c)) for c in cols_sorted) + " |")
        return "\n".join([header, sep] + body)

    # Validate inputs
    if not isinstance(code, str) or not code.strip():
        _log("error", error={"code": "VALIDATION_ERROR", "message": "code must be a non-empty string"})
        return _err("VALIDATION_ERROR", "code must be a non-empty string")
    if not isinstance(year, str) or len(year) != 4 or not year.isdigit():
        _log("error", error={"code": "VALIDATION_ERROR", "message": "year must be a 4-digit string like '2023'"})
        return _err("VALIDATION_ERROR", "year must be a 4-digit string like '2023'")
    if not isinstance(quarter, int):
        _log("error", error={"code": "VALIDATION_ERROR", "message": "quarter must be an integer in [1,4]"})
        return _err("VALIDATION_ERROR", "quarter must be an integer in [1,4]")
    if quarter < 1 or quarter > 4:
        _log("error", error={"code": "VALIDATION_ERROR", "message": "quarter must be in [1,4]"})
        return _err("VALIDATION_ERROR", "quarter must be in [1,4]")

    # Resolve code -> security
    secs = _load("securities.json")
    sec = None
    for s in secs:
        if isinstance(s, dict) and s.get("bs_code") == code:
            sec = s
            break
    if not sec:
        _log("error", error={"code": "NOT_FOUND", "message": "security code not found"})
        return _err("NOT_FOUND", "security code not found", code=code)

    fam = _load("fundamentals_and_macro.json")
    matches = []
    for r in fam:
        if not isinstance(r, dict):
            continue
        if r.get("dataset_type") != "profit":
            continue
        if r.get("status") != "active":
            continue
        if r.get("security_id") != sec.get("id"):
            continue
        if r.get("year") != year:
            continue
        if r.get("quarter") != quarter:
            continue
        matches.append(r)

    # Return empty set as normal response
    out_rows = []
    for r in matches:
        out_rows.append({
            "dataset_type": r.get("dataset_type"),
            "security_id": r.get("security_id"),
            "year": r.get("year"),
            "quarter": r.get("quarter"),
            "payload": r.get("payload"),
            "updated_at": r.get("updated_at"),
        })

    resp = {
        "code": code,
        "security_id": sec.get("id"),
        "year": year,
        "quarter": quarter,
        "total": len(out_rows),
        "data": out_rows,
        "markdown": _md_table(out_rows) if out_rows else "",
    }
    _log("ok", total=len(out_rows))
    return resp

