    def _err(code_, msg, **x):
        return {"error": {"code": code_, "message": msg, **x}}

    t0 = time.time()
    endpoint = "get_cash_flow_data"

    # Request logging (best-effort: create file if absent)
    def _log(status, credential_used=None, error_code=None):
        try:
            logs = _load("request_logs.json")
            now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
            logs.append({
                "id": f"req_{int(time.time()*1000)}_{os.getpid()}_{len(logs)+1}",
                "endpoint": endpoint,
