                "error_code": error_code,
                "latency_ms": int((time.time() - t0) * 1000),
                "timestamp": now
            })
            _save("request_logs.json", logs)
        except Exception:
            # Never fail the request because logging failed
            pass

    # Validate inputs
    if not isinstance(code, str) or not code.strip():
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "code must be a non-empty string")
    if not isinstance(year, str) or not re.fullmatch(r"\d{4}", year.strip()):
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "year must be a 4-digit string 'YYYY'")
    if not isinstance(quarter, int):
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "quarter must be an integer")
    if quarter < 1 or quarter > 4:
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "quarter must be in [1, 4]")

    code = code.strip()
    year = year.strip()

    # Resolve security by bs_code (no implicit creation)
    securities = _load("securities.json")
    sec = next((s for s in securities if isinstance(s, dict) and s.get("bs_code") == code), None)
