        if r.get("status") != "active":
            continue
        if r.get("security_id") != sec.get("id"):
            continue
        if r.get("year") != year:
            continue
        if r.get("quarter") != quarter:
            continue
        rows.append(r)

    # Sort stable by updated_at then id (if multiple active exist, still return deterministic)
    def _key(r):
        ua = r.get("updated_at") or ""
        return (ua, r.get("id") or "")
    rows.sort(key=_key)

    # Build markdown table (vendor-like)
    def _to_md_table(items):
        if not items:
            return ""
        # Flatten payload keys for headers (keep deterministic)
        keys = set()
        for it in items:
            payload = it.get("payload")
            if isinstance(payload, dict):
                for k in payload.keys():
                    keys.add(k)
        payload_keys = sorted(keys)
        headers = ["code", "year", "quarter"] + payload_keys
        lines = []
        lines.append("| " + " | ".join(headers) + " |")
        lines.append("| " + " | ".join(["---"] * len(headers)) + " |")
        for it in items:
            payload = it.get("payload") if isinstance(it.get("payload"), dict) else {}
            row = [code, year, str(quarter)]
            for k in payload_keys:
                v = payload.get(k, "")
                if isinstance(v, (dict, list)):
                    v = json.dumps(v, ensure_ascii=False)
                row.append("" if v is None else str(v))
            lines.append("| " + " | ".join(row) + " |")
        return "\n".join(lines)

    _log("ok")
    return {
        "code": code,
        "security_id": sec.get("id"),
        "dataset_type": "cash_flow",
        "year": year,
        "quarter": quarter,
        "total": len(rows),
        "data": rows,
        "markdown": _to_md_table(rows)
    }

