def get_stock_industry(code=None, date=None, **_extra):
    import json, os, datetime
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0362000" if __import__("os").path.isdir("./environment_mix/0362000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    _t0 = datetime.datetime.utcnow()

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _audit(endpoint, params, status, error_code=None):
        # Best-effort: never fail the request because of logging.
        try:
            logs = _load("request_logs.json")
            if not isinstance(logs, list):
                logs = []
            latency_ms = int((datetime.datetime.utcnow() - _t0).total_seconds() * 1000)
            row = {
                "id": f"req_{datetime.datetime.utcnow().strftime('%Y%m%d%H%M%S%f')}",
                "endpoint": endpoint,
                "params": params,
                "status": status,
                "latency_ms": latency_ms,
                "timestamp": _now_iso(),
            }
            if error_code is not None:
                row["error_code"] = error_code
            logs.append(row)
            _save("request_logs.json", logs)
        except Exception:
            pass

    def _parse_ymd(s, field):
        if s is None:
            return None, None
        if not isinstance(s, str):
            return None, _err("VALIDATION_ERROR", f"{field} must be a string in YYYY-MM-DD format or null", field=field)
        try:
            return datetime.datetime.strptime(s, "%Y-%m-%d").date(), None
        except ValueError:
            return None, _err("VALIDATION_ERROR", f"{field} must be in YYYY-MM-DD format", field=field)

    def _to_date(x):
        if x is None:
            return None
        if isinstance(x, datetime.date) and not isinstance(x, datetime.datetime):
            return x
        if isinstance(x, datetime.datetime):
            return x.date()
        if isinstance(x, str):
            try:
                return datetime.datetime.strptime(x[:10], "%Y-%m-%d").date()
            except ValueError:
                return None
        return None

    endpoint = "get_stock_industry"
    params_for_log = {"code": code, "date": date}

    if code is not None and not isinstance(code, str):
        _audit(endpoint, params_for_log, "error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "code must be a string (bs_code) or null", field="code")
    if code is not None and not code.strip():
        _audit(endpoint, params_for_log, "error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "code must be a non-empty string or null", field="code")

    qd, e = _parse_ymd(date, "date")
    if e:
        _audit(endpoint, params_for_log, "error", "VALIDATION_ERROR")
        return e

    securities = _load("securities.json")
    refs = _load("reference_classifications.json")
    if not isinstance(securities, list) or not isinstance(refs, list):
        _audit(endpoint, params_for_log, "error", "NOT_FOUND")
        return _err("NOT_FOUND", "Reference data is unavailable")

    sec_by_bs = {}
    sec_by_id = {}
    for s in securities:
        if isinstance(s, dict):
            sid = s.get("id")
            bs = s.get("bs_code")
            if isinstance(sid, str):
                sec_by_id[sid] = s
            if isinstance(bs, str):
                sec_by_bs[bs] = s

    security_id = None
    if code is not None:
        sec = sec_by_bs.get(code)
        if not sec:
            _audit(endpoint, params_for_log, "error", "NOT_FOUND")
            return _err("NOT_FOUND", "code not found in securities master list", code=code)
        security_id = sec.get("id")

    # Pick as_of_date: if date is null -> latest available for ref_type='industry'; else exact match to date.
    industry_rows = []
    for r in refs:
        if not isinstance(r, dict):
            continue
        if r.get("ref_type") != "industry":
            continue
        if r.get("status") != "active":
            continue
        sid = r.get("security_id")
        if not isinstance(sid, str) or sid not in sec_by_id:
            # Enforce FK integrity: ignore orphaned rows rather than raising.
            continue
        if security_id is not None and sid != security_id:
            continue
        aod = _to_date(r.get("as_of_date"))
        if aod is None:
            continue
        industry_rows.append((aod, r))

    if qd is None:
        if not industry_rows:
            _audit(endpoint, params_for_log, "ok")
            return {"as_of_date": None, "count": 0, "rows": []}
        chosen_date = max(aod for aod, _ in industry_rows)
    else:
        chosen_date = qd

    out_rows = []
    for aod, r in industry_rows:
        if aod != chosen_date:
            continue
        sid = r.get("security_id")
        sec = sec_by_id.get(sid)
        if not sec:
            continue
        out_rows.append({
            "as_of_date": chosen_date.isoformat(),
            "bs_code": sec.get("bs_code"),
            "name": sec.get("name"),
            "industry_code": r.get("industry_code"),
            "industry_name": r.get("industry_name"),
        })

    # Deterministic ordering
    out_rows.sort(key=lambda x: (x.get("bs_code") or "", x.get("industry_code") or "", x.get("industry_name") or ""))

    _audit(endpoint, params_for_log, "ok")
    return {"as_of_date": chosen_date.isoformat() if chosen_date else None, "count": len(out_rows), "rows": out_rows}

