        )
    md = "\n".join(md_lines) + "\n"

    _audit(endpoint, params_for_log, "OK")
    return {"data": {"markdown": md, "as_of_date": chosen_asof.strftime("%Y-%m-%d"), "index_code": "sz50", "rows": out, "total": len(out)}}

