        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    _t0 = datetime.datetime.utcnow()

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_ymd(s, field):
        if s is None:
            return None, None
        if not isinstance(s, str):
            return None, _err("VALIDATION_ERROR", f"{field} must be a string in 'YYYY-MM-DD' format or null")
        try:
            d = datetime.datetime.strptime(s, "%Y-%m-%d").date()
            return d, None
        except ValueError:
            return None, _err("VALIDATION_ERROR", f"{field} must be in 'YYYY-MM-DD' format")

    def _to_date(x):
        if x is None:
            return None
        if isinstance(x, datetime.date) and not isinstance(x, datetime.datetime):
            return x
        if isinstance(x, datetime.datetime):
            return x.date()
        if isinstance(x, str):
            try:
                return datetime.datetime.strptime(x[:10], "%Y-%m-%d").date()
            except ValueError:
                return None
        return None

    def _audit(endpoint, params, status):
        try:
            logs = _load("request_logs.json")
            if not isinstance(logs, list):
                logs = []
            latency_ms = int((datetime.datetime.utcnow() - _t0).total_seconds() * 1000)
            logs.append({
                "id": f"req_{datetime.datetime.utcnow().strftime('%Y%m%d%H%M%S%f')}",
                "endpoint": endpoint,
                "params": params,
                "status": status,
                "latency_ms": latency_ms,
                "timestamp": _now_iso()
            })
            _save("request_logs.json", logs)
        except Exception:
            pass

    endpoint = "get_zz500_stocks"
    params_for_log = {"date": date}

    parsed_date, e = _parse_ymd(date, "date")
    if e:
        _audit(endpoint, params_for_log, "VALIDATION_ERROR")
        return e

    securities = _load("securities.json")
    ref = _load("reference_classifications.json")

    rows = []
    for r in ref:
        if not isinstance(r, dict):
            continue
        if r.get("ref_type") != "index_constituent":
            continue
        if r.get("index_code") != "zz500":
            continue
        if r.get("status") != "active":
            continue
        sid = r.get("security_id")
        if not any(isinstance(s, dict) and s.get("id") == sid for s in securities):
            continue
        rows.append(r)

    chosen_asof = None
    if parsed_date is not None:
        chosen_asof = parsed_date
    else:
        max_d = None
        for r in rows:
            d = _to_date(r.get("as_of_date"))
            if d is None:
                continue
            if max_d is None or d > max_d:
                max_d = d
        chosen_asof = max_d

    if chosen_asof is None:
        md = "| bs_code | name | as_of_date | index_code | weight |\n|---|---|---|---|---|\n"
        _audit(endpoint, params_for_log, "OK")
        return {"data": {"markdown": md, "as_of_date": None, "index_code": "zz500", "rows": [], "total": 0}}

    chosen = []
    for r in rows:
        if _to_date(r.get("as_of_date")) != chosen_asof:
            continue
        chosen.append(r)

