            "weight": r.get("weight"),
        })

    out.sort(key=lambda x: (-(x["weight"] if isinstance(x["weight"], (int, float)) else -1), x["bs_code"] or ""))

    md_lines = [
        "| bs_code | name | as_of_date | index_code | weight |",
        "|---|---|---|---|---|",
    ]
