        def _cell(v):
            if v is None:
                return ""
            return str(v).replace("\n", " ").replace("|", "\\|")
        md_lines.append(
            f"| {_cell(row['bs_code'])} | {_cell(row['name'])} | {_cell(row['as_of_date'])} | {_cell(row['index_code'])} | {_cell(row['weight'])} |"
