    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    _t0 = datetime.datetime.utcnow()

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _audit(status, error_code=None, **extra):
        # Best-effort audit; never blocks the request
        try:
            logs = _load("request_logs.json")
            if not isinstance(logs, list):
                logs = []
            latency_ms = int((datetime.datetime.utcnow() - _t0).total_seconds() * 1000)
            row = {
                "id": f"req_{datetime.datetime.utcnow().strftime('%Y%m%d%H%M%S%f')}",
                "endpoint": "get_trade_dates",
                "params": {"start_date": start_date, "end_date": end_date},
                "status": status,
                "latency_ms": latency_ms,
                "timestamp": _now_iso(),
            }
            if error_code is not None:
                row["error_code"] = error_code
            row.update(extra)
            logs.append(row)
            _save("request_logs.json", logs)
        except Exception:
            pass

    def _parse_yyyy_mm_dd(s, field):
        if s is None:
            return None, None
        if not isinstance(s, str):
            return None, _err("VALIDATION_ERROR", f"{field} must be a string in YYYY-MM-DD format or null", field=field)
        try:
            return datetime.datetime.strptime(s, "%Y-%m-%d").date(), None
        except ValueError:
            return None, _err("VALIDATION_ERROR", f"{field} must be in YYYY-MM-DD format", field=field)

    def _to_date(v):
        if v is None:
            return None
        if isinstance(v, datetime.datetime):
            return v.date()
        if isinstance(v, datetime.date):
            return v
        if isinstance(v, str):
            try:
                return datetime.datetime.strptime(v[:10], "%Y-%m-%d").date()
            except ValueError:
                return None
        return None

    sd, e = _parse_yyyy_mm_dd(start_date, "start_date")
    if e:
        _audit("error", "VALIDATION_ERROR")
        return e
    ed, e = _parse_yyyy_mm_dd(end_date, "end_date")
    if e:
        _audit("error", "VALIDATION_ERROR")
        return e

    if sd is None:
        sd = datetime.date(2015, 1, 1)
    if ed is None:
        ed = datetime.datetime.utcnow().date()

    if sd > ed:
        err = _err("VALIDATION_ERROR", "start_date must be on or before end_date", start_date=str(sd), end_date=str(ed))
        _audit("error", "VALIDATION_ERROR")
        return err

    cal = _load("market_calendar.json")
    if not isinstance(cal, list) or len(cal) == 0:
        err = _err("NOT_FOUND", "No trading calendar is available")
        _audit("error", "NOT_FOUND")
        return err

    # Business rule: respond only with dates present in the calendar; however, for this datastore the calendar
    # may be a partial snapshot. Realistic behavior: return the intersection for the requested range, and only
    # raise NOT_FOUND when there is no coverage at all within the range.
    rows_in_range = []
    for r in cal:
        td = _to_date(r.get("trading_date"))
        if td is None:
            continue
        if sd <= td <= ed:
            rows_in_range.append((td, r))

    if not rows_in_range:
        err = _err(
            "NOT_FOUND",
            "No trading calendar is available for the requested range",
            start_date=sd.isoformat(),
            end_date=ed.isoformat(),
        )
        _audit("error", "NOT_FOUND")
        return err

    rows_in_range.sort(key=lambda x: x[0])
    trade_dates = [d.isoformat() for (d, r) in rows_in_range if bool(r.get("is_trade_day")) is True]

    resp = {
        "start_date": sd.isoformat(),
        "end_date": ed.isoformat(),
        "trade_dates": trade_dates,
        "total": len(trade_dates),
        "coverage": {
            "calendar_rows_in_range": len(rows_in_range),
            "calendar_first_date": rows_in_range[0][0].isoformat(),
            "calendar_last_date": rows_in_range[-1][0].isoformat(),
        },
    }
    _audit("success")
    return resp

