                row["error_code"] = error_code
            row.update(extra)
            logs.append(row)
            _save("request_logs.json", logs)
        except Exception:
            pass

    def _parse_yyyy_mm_dd(s, field):
        if s is None:
            return None, None
        if not isinstance(s, str):
            return None, _err("VALIDATION_ERROR", f"{field} must be a string in YYYY-MM-DD format or null", field=field)
        try:
            return datetime.datetime.strptime(s, "%Y-%m-%d").date(), None
        except ValueError:
            return None, _err("VALIDATION_ERROR", f"{field} must be in YYYY-MM-DD format", field=field)

    def _to_date(v):
        if v is None:
            return None
        if isinstance(v, datetime.datetime):
            return v.date()
        if isinstance(v, datetime.date):
            return v
        if isinstance(v, str):
            try:
                return datetime.datetime.strptime(v[:10], "%Y-%m-%d").date()
            except ValueError:
                return None
        return None

    d, e = _parse_yyyy_mm_dd(date, "date")
    if e:
        _audit("error", "VALIDATION_ERROR")
        return e
    if d is None:
        d = datetime.datetime.utcnow().date()

    secs = _load("securities.json")
    if not isinstance(secs, list) or len(secs) == 0:
        err = _err("NOT_FOUND", "No securities master list is available")
        _audit("error", "NOT_FOUND")
        return err

    # The API description mentions "as of the given date" and "NOT_FOUND when the server has no reference snapshot
    # for that date". This server models the instrument universe in securities.json (with lifecycle + listing/delist).
    # Therefore, a snapshot exists if we have any securities at all; do not incorrectly require a separate snapshot.
    out = []
    for s in secs:
        bs_code = s.get("bs_code")
        name = s.get("name")
        status = s.get("status")
        sec_type = s.get("security_type")
        if not isinstance(bs_code, str) or not isinstance(name, str) or not isinstance(status, str):
            continue

        listing = _to_date(s.get("listing_date"))
        delisting = _to_date(s.get("delisting_date"))

        # "as-of" filtering: if listing_date exists and is after query date, exclude.
        if listing is not None and listing > d:
            continue
        # If delisted and delisting_date exists and is before query date, still include (status indicates delisted).
        # If delisting_date exists and is before date but status isn't delisted, keep as stored (do not invent status).

        out.append({
            "code": bs_code,          # client-facing code
            "code_name": name,        # typical vendor naming
            "status": status,
            "exchange": s.get("exchange"),
            "security_type": sec_type,
        })

    # Stable ordering: exchange then code
    out.sort(key=lambda r: ((r.get("exchange") or ""), (r.get("code") or "")))

    resp = {
        "date": d.isoformat(),
        "items": out,
        "total": len(out),
    }
    _audit("success")
    return resp

