    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    def _parse_yyyy_mm_dd(s, field):
        if s is None:
            return None, None
        if not isinstance(s, str):
            return None, _err("VALIDATION_ERROR", f"{field} must be a string in YYYY-MM-DD format or null", field=field)
        try:
