        except ValueError:
            return None, _err("VALIDATION_ERROR", f"{field} must be in YYYY-MM-DD format", field=field)

    def _as_date(val):
        if isinstance(val, str) and len(val) >= 10:
            try:
                return datetime.datetime.strptime(val[:10], "%Y-%m-%d").date()
            except Exception:
                return None
        return None

    def _md_escape(s):
        s = "" if s is None else str(s)
        return s.replace("|", "\\|").replace("\n", " ").strip()

    try:
        sd, e = _parse_yyyy_mm_dd(start_date, "start_date")
        if e: return e
        ed, e = _parse_yyyy_mm_dd(end_date, "end_date")
        if e: return e

        if sd is None:
            sd = datetime.date(2015, 1, 1)
        if ed is None:
            ed = datetime.datetime.utcnow().date()

        if sd > ed:
            return _err("VALIDATION_ERROR", "start_date must be on or before end_date", start_date=sd.isoformat(), end_date=ed.isoformat())

        fam = _load("fundamentals_and_macro.json")
        if not isinstance(fam, list):
            return _err("NOT_FOUND", "Dataset is unavailable")

        rows = []
        for r in fam:
            if not isinstance(r, dict):
                continue
            if r.get("dataset_type") != "deposit_rate":
                continue
            if r.get("status") != "active":
                continue
            d = _as_date(r.get("as_of_date"))
            if d is None:
                continue
            if sd <= d <= ed:
                payload = r.get("payload")
                if not isinstance(payload, dict):
                    payload = {}
                rows.append((d, payload))

        rows.sort(key=lambda x: x[0])
        # Build a stable set of columns from payload keys (vendor-like: wide table)
        col_keys = []
        seen = set()
        for _, p in rows:
            for k in p.keys():
                if k not in seen:
                    seen.add(k)
                    col_keys.append(k)

        headers = ["date"] + col_keys
        md = []
        md.append("| " + " | ".join(_md_escape(h) for h in headers) + " |")
        md.append("| " + " | ".join(["---"] * len(headers)) + " |")
        for d, p in rows:
            line = [d.isoformat()] + [p.get(k, "") for k in col_keys]
            md.append("| " + " | ".join(_md_escape(v) for v in line) + " |")

        return {
            "data": {
                "start_date": sd.isoformat(),
                "end_date": ed.isoformat(),
                "count": len(rows),
                "markdown": "\n".join(md)
            }
        }
    except Exception as ex:
        return _err("NOT_FOUND", "Unexpected server condition", details=str(ex))

