    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = datetime.datetime.utcnow()

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_ymd(s):
        # Accept 'YYYY-MM-DD' only
        if not isinstance(s, str):
            return None
        try:
            return datetime.datetime.strptime(s, "%Y-%m-%d").date()
        except ValueError:
            return None

    def _to_date(v):
        if v is None:
            return None
        if isinstance(v, str):
            # try ISO first then YYYY-MM-DD
            try:
                return datetime.datetime.fromisoformat(v.replace("Z", "+00:00")).date()
            except ValueError:
                d = _parse_ymd(v)
                return d
        return None

