            "id": "req_" + now.strftime("%Y%m%d%H%M%S") + "_" + str(len(jobs) + 1),
            "job_type": "macro_rates",
            "vendor": "baostock",
            "requested_params": {"endpoint": endpoint, **(params or {})},
            "dataset_fingerprint": None,
            "row_count": int(matched) if matched is not None else None,
            "started_at": _now_iso(),
            "finished_at": _now_iso(),
            "status": "succeeded" if status < 400 else "failed",
            "error_message": None if error is None else (error.get("message") if isinstance(error, dict) else str(error)),
            "created_at": _now_iso(),
