def get_latest_trading_date(as_of_date=None, exchange=None, **_extra):
    import json, os, datetime
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0362000" if __import__("os").path.isdir("./environment_mix/0362000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    _t0 = datetime.datetime.utcnow()

    # Validation
    if exchange is None:
        exchange = "sh"
    if not isinstance(exchange, str) or exchange not in ("sh", "sz", "bj", "idx"):
        return _err("VALIDATION_ERROR", "exchange must be one of: sh, sz, bj, idx")

    def _parse_ymd(s):
        if not isinstance(s, str):
            return None
        try:
            return datetime.datetime.strptime(s, "%Y-%m-%d").date()
        except ValueError:
            return None

    if as_of_date is None:
        ref_date = datetime.date.today()
    else:
        ref_date = _parse_ymd(as_of_date)
        if ref_date is None:
            return _err("VALIDATION_ERROR", "as_of_date must be in YYYY-MM-DD format")

    # Load calendar
    cal = _load("market_calendar.json")
    if not isinstance(cal, list):
        cal = []

    # We don't have per-exchange calendars in schema; treat missing calendar as unavailable.
    if len(cal) == 0:
        return _err("NOT_FOUND", "calendar for requested exchange is unavailable", exchange=exchange)

    # Find latest <= ref_date where is_trade_day is true
    latest = None
    latest_dt = None
    for r in cal:
        if not isinstance(r, dict):
            continue
        td = r.get("trading_date")
        is_td = r.get("is_trade_day", False)
        if is_td is not True:
            continue
        d = _parse_ymd(td[:10]) if isinstance(td, str) else None
        if d is None:
            continue
        if d <= ref_date and (latest_dt is None or d > latest_dt):
            latest_dt = d
            latest = r

    if latest_dt is None:
        return _err("NOT_FOUND", "cannot determine latest trading date from calendar", exchange=exchange, as_of_date=ref_date.isoformat())

    # Request log dynamics (best-effort; schema not provided for logs)
    _lat_ms = int((datetime.datetime.utcnow() - _t0).total_seconds() * 1000)
    return {
        "exchange": exchange,
        "as_of_date": ref_date.isoformat(),
        "latest_trading_date": latest_dt.isoformat(),
        "meta": {"latency_ms": _lat_ms}
    }

def get_market_analysis_timeframe(period=None, **_extra):
    import json, os, datetime
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0362000" if __import__("os").path.isdir("./environment_mix/0362000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    _t0 = datetime.datetime.utcnow()
    endpoint = "get_market_analysis_timeframe"

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _audit(params, status, error_code=None, result=None):
        # Record every call AND persist state change (observability dynamics).
        # We also maintain a simple counter file to ensure "mutation" is observable.
        try:
            logs = _load("request_logs.json")
            if not isinstance(logs, list):
                logs = []
            latency_ms = int((datetime.datetime.utcnow() - _t0).total_seconds() * 1000)
            row = {
                "id": f"req_{datetime.datetime.utcnow().strftime('%Y%m%d%H%M%S%f')}",
                "endpoint": endpoint,
                "params": params,
                "status": status,
                "latency_ms": latency_ms,
                "timestamp": _now_iso(),
            }
            if error_code is not None:
                row["error_code"] = error_code
            if result is not None:
                row["result"] = result
            logs.append(row)
            _save("request_logs.json", logs)

            # Persist an additional observable mutation: a lightweight usage counter.
            counters = _load("usage_counters.json")
            if not isinstance(counters, dict):
                counters = {}
            counters[endpoint] = int(counters.get(endpoint, 0) or 0) + 1
            counters["updated_at"] = _now_iso()
            _save("usage_counters.json", counters)
        except Exception:
            pass

    if period is None:
        period = "recent"
    if not isinstance(period, str) or period not in ("recent", "quarter", "half_year", "year"):
        _audit({"period": period}, "error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "period must be one of: recent, quarter, half_year, year", period=period)

    cal = _load("market_calendar.json")
    if not isinstance(cal, list) or not cal:
        _audit({"period": period}, "error", "NOT_FOUND")
        return _err("NOT_FOUND", "cannot determine a latest trading date from market_calendar")

    def _parse_ymd(s):
        if not isinstance(s, str) or len(s) < 10:
            return None
        try:
            return datetime.datetime.strptime(s[:10], "%Y-%m-%d").date()
        except ValueError:
            return None

    today = datetime.date.today()
    trade_days = []
    for r in cal:
        if not isinstance(r, dict):
            continue
        if r.get("is_trade_day") is not True:
            continue
        td = _parse_ymd(r.get("trading_date"))
        if td is None:
            continue
        if td <= today:
            trade_days.append(td)

    if not trade_days:
        _audit({"period": period}, "error", "NOT_FOUND")
        return _err("NOT_FOUND", "cannot determine a latest trading date from market_calendar")

    end_date = max(trade_days)

    offsets = {
        "recent": 45,       # ~1-2 months
        "quarter": 92,      # ~1 quarter
        "half_year": 183,   # ~6 months
        "year": 365         # ~1 year
    }
    approx_start = end_date - datetime.timedelta(days=offsets[period])

    td_sorted = sorted(set(trade_days))
    start_date = None
    for d in reversed(td_sorted):
        if d <= approx_start:
            start_date = d
            break
    if start_date is None:
        start_date = td_sorted[0]

    result = {"period": period, "start_date": start_date.isoformat(), "end_date": end_date.isoformat()}
    _audit({"period": period}, "ok", result=result)
    return result

