        if d > latest_td:
            continue
        c = r.get("close")
        if isinstance(c, (int, float)):
            closes.append((d, float(c)))
        if latest_k_date is None or d > latest_k_date:
            latest_k_date = d
            latest_k = r

    closes.sort(key=lambda x: x[0])

    # Fundamentals: pick most recent quarter (by year, quarter) active rows for the per-stock dataset types.
    q_types = ("profit", "operation", "growth", "balance", "cash_flow", "dupont")
    latest_f = {}  # dataset_type -> row
    def _yq_key(row):
        y = row.get("year")
        q = row.get("quarter")
        if not (isinstance(y, str) and y.isdigit() and len(y) == 4 and isinstance(q, int) and 1 <= q <= 4):
            return None
        return (int(y), int(q))

    for r in fam:
        if not isinstance(r, dict):
            continue
        if r.get("status") != "active":
            continue
        dt = r.get("dataset_type")
        if dt not in q_types:
            continue
        if r.get("security_id") != security_id:
            continue
        k = _yq_key(r)
        if k is None:
            continue
        prev = latest_f.get(dt)
        if prev is None or _yq_key(prev) < k:
            latest_f[dt] = r

    # Industry classification: latest as_of_date active for this security
    refs = _load("reference_classifications.json")
    if not isinstance(refs, list):
        refs = []
    latest_ind = None
    latest_ind_d = None
    for r in refs:
        if not isinstance(r, dict):
            continue
        if r.get("status") != "active":
            continue
        if r.get("ref_type") != "industry":
            continue
        if r.get("security_id") != security_id:
            continue
        ad = r.get("as_of_date")
        d = _parse_ymd(ad[:10]) if isinstance(ad, str) else None
        if d is None:
            continue
        if latest_ind_d is None or d > latest_ind_d:
            latest_ind_d = d
            latest_ind = r

    # Technical metrics (from stored kline only)
    def _sma(vals):
        if not vals:
            return None
        return sum(vals) / float(len(vals))

    tech = {}
    if closes:
        last_close = closes[-1][1]
        tech["last_close"] = last_close
        # 20/60 day SMAs (using last N observations, not calendar days)
        last20 = [v for _, v in closes[-20:]]
        last60 = [v for _, v in closes[-60:]]
        if len(last20) >= 5:
            tech["sma_20"] = _sma(last20)
        if len(last60) >= 10:
            tech["sma_60"] = _sma(last60)
        # simple return over 20 trading days if available
        if len(closes) >= 21:
            prev20 = closes[-21][1]
            if prev20 != 0:
                tech["return_20d"] = (last_close / prev20) - 1.0
        # volatility over 20 trading days (stdev of daily returns)
        if len(closes) >= 22:
            rets = []
            for i in range(len(closes) - 21, len(closes)):
                p0 = closes[i - 1][1]
                p1 = closes[i][1]
                if p0 and p0 != 0:
                    rets.append((p1 / p0) - 1.0)
            if len(rets) >= 5:
                m = sum(rets) / len(rets)
                v = sum((x - m) ** 2 for x in rets) / (len(rets) - 1) if len(rets) > 1 else 0.0
                tech["volatility_20d"] = math.sqrt(v)

    # Fundamental summary: we only report what exists in payload; we avoid claiming specific fields.
    fund = {}
    for dt, row in latest_f.items():
        payload = row.get("payload")
        k = _yq_key(row)
        if isinstance(payload, dict) and k is not None:
            fund[dt] = {
                "year": str(k[0]),
                "quarter": k[1],
                "available_fields": sorted([str(x) for x in payload.keys()])[:200]  # cap to keep response sane
            }

    # Required datasets availability per analysis_type
    if analysis_type in ("technical", "comprehensive") and not closes:
        return _err("NOT_FOUND", "required datasets are not available for technical analysis (no kline data)", code=code)
    if analysis_type in ("fundamental", "comprehensive") and not latest_f:
        return _err("NOT_FOUND", "required datasets are not available for fundamental analysis (no quarterly fundamentals)", code=code)

    report = {
        "code": code,
        "security": {
            "id": security_id,
            "bs_code": sec.get("bs_code"),
            "exchange": sec.get("exchange"),
            "symbol": sec.get("symbol"),
            "name": sec.get("name"),
            "status": sec.get("status"),
            "security_type": sec.get("security_type"),
            "listing_date": (sec.get("listing_date")[:10] if isinstance(sec.get("listing_date"), str) else sec.get("listing_date")),
            "delisting_date": (sec.get("delisting_date")[:10] if isinstance(sec.get("delisting_date"), str) else sec.get("delisting_date")),
        },
        "as_of": {
            "latest_trading_date": latest_td.isoformat(),
            "latest_kline_date": latest_k_date.isoformat() if latest_k_date else None
        },
        "industry": None,
        "analysis_type": analysis_type,
        "fundamental": None,
        "technical": None,
        "notes": [
            "This report is data-driven and derived only from locally stored datasets (no external calls).",
            "Field availability depends on what is present in stored payloads; missing metrics are not inferred."
        ]
    }

    if latest_ind is not None:
        report["industry"] = {
            "as_of_date": latest_ind_d.isoformat() if latest_ind_d else None,
            "industry_code": latest_ind.get("industry_code"),
            "industry_name": latest_ind.get("industry_name")
        }

    if analysis_type in ("fundamental", "comprehensive"):
        report["fundamental"] = {
            "latest_quarterly_datasets": fund,
            "coverage": {
                "datasets_present": sorted(list(latest_f.keys())),
                "datasets_missing": sorted([t for t in q_types if t not in latest_f])
            }
        }

    if analysis_type in ("technical", "comprehensive"):
        # Include only metrics we computed from stored kline
        report["technical"] = {
            "metrics": tech,
            "kline_basis": {
                "series_constraints": {"frequency": "d", "adjust_flag": "3", "status": "active"},
                "observations_used": len(closes)
            }
        }

    if analysis_type == "comprehensive":
        # A minimal synthesis that does not invent absent fields
        syn = []
        if report["industry"] and report["industry"].get("industry_name"):
            syn.append("Industry classification available.")
        if closes:
            syn.append("Recent price history available for technical indicators.")
        if latest_f:
            syn.append("Quarterly fundamentals payloads available (field set varies by dataset).")
        report["summary"] = " ".join(syn) if syn else "Insufficient stored data for summary."

    return report

def list_securities(exchange=None, security_type=None, status=None, query=None, listing_date_gte=None, listing_date_lte=None, page=None, page_size=None, order_by=None, order=None, **_extra):
    import json, os, datetime
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0362000" if __import__("os").path.isdir("./environment_mix/0362000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    # Validate enums per tool (even if underlying store differs)
    if exchange not in (None, "sh", "sz"):
        return _err("VALIDATION_ERROR", "exchange must be one of: sh, sz, null")
    if status not in (None, "active", "suspended", "delisted"):
        return _err("VALIDATION_ERROR", "status must be one of: active, suspended, delisted, null")
    allowed_sec_types = (None, "stock", "index", "etf", "fund", "bond", "other", None)
    if security_type not in allowed_sec_types:
        return _err("VALIDATION_ERROR", "security_type must be one of: stock, index, etf, fund, bond, other, null")

    def _parse_ymd(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return None
        try:
            return datetime.datetime.strptime(s, "%Y-%m-%d").date()
        except ValueError:
            return None

    if listing_date_gte is not None and _parse_ymd(listing_date_gte) is None:
        return _err("VALIDATION_ERROR", "listing_date_gte must be in YYYY-MM-DD format or null")
    if listing_date_lte is not None and _parse_ymd(listing_date_lte) is None:
        return _err("VALIDATION_ERROR", "listing_date_lte must be in YYYY-MM-DD format or null")

    if page is None:
        page = 1
    if page_size is None:
        page_size = 50
    if not isinstance(page, int) or page < 1:
        return _err("VALIDATION_ERROR", "page must be an integer >= 1")
    if not isinstance(page_size, int) or page_size < 1 or page_size > 500:
        return _err("VALIDATION_ERROR", "page_size must be an integer between 1 and 500")

    if order_by is None:
        order_by = "bs_code"
    if order_by not in ("bs_code", "symbol", "listing_date", "updated_at"):
        return _err("VALIDATION_ERROR", "order_by must be one of: bs_code, symbol, listing_date, updated_at")

    if order is None:
        order = "asc"
    if order not in ("asc", "desc"):
        return _err("VALIDATION_ERROR", "order must be one of: asc, desc")

    # Tool's security_type enums don't match store schema (equity/index). Map where possible.
    def _map_sec_type_filter(st):
        if st is None:
            return None
        if st == "index":
            return "index"
        if st == "stock":
            return "equity"
        # etf/fund/bond/other not represented; treat as no matches.
        return "__NO_MATCH__"

    mapped = _map_sec_type_filter(security_type)
    if mapped == "__NO_MATCH__":
        return {
            "data": [],
            "page": page,
            "page_size": page_size,
            "total": 0,
            "has_more": False,
            "next_cursor": None
        }

    secs = _load("securities.json")
    if not isinstance(secs, list):
        secs = []

    q = query.lower().strip() if isinstance(query, str) and query.strip() else None
    gte = _parse_ymd(listing_date_gte) if listing_date_gte is not None else None
    lte = _parse_ymd(listing_date_lte) if listing_date_lte is not None else None

    out = []
    for r in secs:
        if not isinstance(r, dict):
            continue

        if exchange is not None and r.get("exchange") != exchange:
            continue
        if status is not None and r.get("status") != status:
            continue
        if mapped is not None and r.get("security_type") != mapped:
            continue

        # listing_date filters: only apply when row has a parsable listing_date
        if gte is not None or lte is not None:
            ld_raw = r.get("listing_date")
            ld = _parse_ymd(ld_raw[:10]) if isinstance(ld_raw, str) else None
            if ld is None:
                continue
            if gte is not None and ld < gte:
                continue
            if lte is not None and ld > lte:
                continue

        if q is not None:
            hay = " ".join([
                str(r.get("symbol") or ""),
                str(r.get("name") or ""),
                str(r.get("bs_code") or "")
            ]).lower()
            if q not in hay:
                continue

        out.append(r)

    def _sort_key(row):
        v = row.get(order_by)
        if order_by in ("listing_date", "updated_at"):
            if isinstance(v, str) and len(v) >= 10:
                return v
            return ""
        if v is None:
            return ""
        return str(v)

    reverse = (order == "desc")
    out.sort(key=_sort_key, reverse=reverse)

    total = len(out)
    start = (page - 1) * page_size
    end = start + page_size
    page_rows = out[start:end]

    has_more = end < total

    # Return stable envelope and avoid fabricating fields
    return {
        "data": page_rows,
        "page": page,
        "page_size": page_size,
        "total": total,
        "has_more": has_more,
        "next_cursor": None
    }

def update_security_status(code, status, effective_date=None, reason=None, **_extra):
    import json, os, datetime
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0362000" if __import__("os").path.isdir("./environment_mix/0362000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    _t0 = datetime.datetime.utcnow()
    endpoint = "update_security_status"

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _audit(params, status_txt, error_code=None):
        try:
            logs = _load("request_logs.json")
            if not isinstance(logs, list):
                logs = []
            latency_ms = int((datetime.datetime.utcnow() - _t0).total_seconds() * 1000)
            row = {
                "id": f"req_{datetime.datetime.utcnow().strftime('%Y%m%d%H%M%S%f')}",
                "endpoint": endpoint,
                "params": params,
                "status": status_txt,
                "latency_ms": latency_ms,
                "timestamp": _now_iso(),
            }
            if error_code is not None:
                row["error_code"] = error_code
            logs.append(row)
            _save("request_logs.json", logs)
        except Exception:
            pass

    def _parse_yyyy_mm_dd(s, field):
        if s is None:
            return None, None
        if not isinstance(s, str):
            return None, _err("VALIDATION_ERROR", f"{field} must be a string in YYYY-MM-DD format or null", field=field)
        try:
            return datetime.datetime.strptime(s, "%Y-%m-%d").date(), None
        except ValueError:
            return None, _err("VALIDATION_ERROR", f"{field} must be in YYYY-MM-DD format", field=field)

    params_for_log = {"code": code, "status": status, "effective_date": effective_date, "reason": reason}

    if not isinstance(code, str) or not code.strip():
        _audit(params_for_log, "error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "code must be a non-empty string (bs_code)", field="code")
    if status not in ("active", "suspended", "delisted"):
        _audit(params_for_log, "error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "status must be one of: active, suspended, delisted", field="status")

    eff, e = _parse_yyyy_mm_dd(effective_date, "effective_date")
    if e:
        _audit(params_for_log, "error", "VALIDATION_ERROR")
        return e
    if reason is not None and not isinstance(reason, str):
        _audit(params_for_log, "error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "reason must be a string or null", field="reason")

    secs = _load("securities.json")
    if not isinstance(secs, list):
        _audit(params_for_log, "error", "NOT_FOUND")
        return _err("NOT_FOUND", "Securities master list is unavailable")

    idx = None
    for i, r in enumerate(secs):
        if isinstance(r, dict) and r.get("bs_code") == code:
            idx = i
            break
    if idx is None:
        _audit(params_for_log, "error", "NOT_FOUND")
        return _err("NOT_FOUND", "code not found in securities master list", code=code)

    row = secs[idx]
    cur = row.get("status")
    transitions = {
        "active": ["suspended", "delisted"],
        "suspended": ["active", "delisted"],
        "delisted": [],
    }
    if cur == status:
        # Idempotent: accept and persist an audit touch (updated_at and optional effective_date note)
        # but no lifecycle transition occurs.
        row["updated_at"] = _now_iso()
        if eff is not None:
            row["status_effective_date"] = eff.isoformat()
        if reason is not None:
            row["status_reason"] = reason
        secs[idx] = row
        _save("securities.json", secs)
        _audit(params_for_log, "ok")
        return {"id": row.get("id"), "bs_code": row.get("bs_code"), "previous_status": cur, "status": status, "effective_date": eff.isoformat() if eff else None}

    if cur not in transitions or status not in transitions[cur]:
        _audit(params_for_log, "error", "INVALID_TRANSITION")
        return _err(
            "INVALID_TRANSITION",
            "invalid status transition per lifecycle rules",
            code=code,
            current_status=cur,
            requested_status=status,
            allowed_transitions=transitions.get(cur, []),
        )

    # Enforce delisting invariants
    if status == "delisted":
        if eff is None:
            # Need a concrete delisting date to satisfy: if status='delisted' then delisting_date is not null
            eff = datetime.datetime.utcnow().date()
        row["delisting_date"] = eff.isoformat() + "T00:00:00Z"
    else:
        # If leaving delisted is not allowed by lifecycle (already covered), but also keep invariant if any stray date
        if row.get("delisting_date") is not None and status != "delisted":
            _audit(params_for_log, "error", "CONFLICT")
            return _err(
                "CONFLICT",
                "cannot set status to non-delisted while delisting_date is present (invariant: if delisting_date is not null then status='delisted')",
                code=code,
                current_status=cur,
                requested_status=status,
            )

    row["status"] = status
    row["updated_at"] = _now_iso()
    if eff is not None:
        row["status_effective_date"] = eff.isoformat()
    if reason is not None:
        row["status_reason"] = reason
    secs[idx] = row
    _save("securities.json", secs)

    _audit(params_for_log, "ok")
    return {
        "id": row.get("id"),
        "bs_code": row.get("bs_code"),
        "previous_status": cur,
        "status": status,
        "effective_date": eff.isoformat() if eff else None,
    }

def update_trade_day(trading_date, is_trade_day, notes=None, **_extra):
    import json, os, datetime
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0362000" if __import__("os").path.isdir("./environment_mix/0362000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    _t0 = datetime.datetime.utcnow()
    endpoint = "update_trade_day"

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _audit(params, status_txt, error_code=None):
        try:
            logs = _load("request_logs.json")
            if not isinstance(logs, list):
                logs = []
            latency_ms = int((datetime.datetime.utcnow() - _t0).total_seconds() * 1000)
            row = {
                "id": f"req_{datetime.datetime.utcnow().strftime('%Y%m%d%H%M%S%f')}",
                "endpoint": endpoint,
                "params": params,
                "status": status_txt,
                "latency_ms": latency_ms,
                "timestamp": _now_iso(),
            }
            if error_code is not None:
                row["error_code"] = error_code
            logs.append(row)
            _save("request_logs.json", logs)
        except Exception:
            pass

    def _parse_yyyy_mm_dd(s):
        if not isinstance(s, str):
            return None
        try:
            return datetime.datetime.strptime(s, "%Y-%m-%d").date()
        except ValueError:
            return None

    params_for_log = {"trading_date": trading_date, "is_trade_day": is_trade_day, "notes": notes}

    d = _parse_yyyy_mm_dd(trading_date)
    if d is None:
        _audit(params_for_log, "error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "trading_date must be in YYYY-MM-DD format", field="trading_date")
    if not isinstance(is_trade_day, bool):
        _audit(params_for_log, "error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "is_trade_day must be boolean", field="is_trade_day")
    if notes is not None and not isinstance(notes, str):
        _audit(params_for_log, "error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "notes must be a string or null", field="notes")

    cal = _load("market_calendar.json")
    if not isinstance(cal, list):
        _audit(params_for_log, "error", "NOT_FOUND")
        return _err("NOT_FOUND", "market_calendar is unavailable")

    # Match rows by date portion; stored values may be ISO with time ("...T00:00:00Z") or plain "YYYY-MM-DD".
    idx = None
    for i, r in enumerate(cal):
        if not isinstance(r, dict):
            continue
        td = r.get("trading_date")
        if isinstance(td, str) and td[:10] == d.isoformat():
            idx = i
            break

    if idx is None:
        # Accept valid updates by creating coverage (relaxed to accept the arguments actually used).
        now = _now_iso()
        new_row = {
            "id": f"as_cal_{datetime.datetime.utcnow().strftime('%Y%m%d%H%M%S%f')}",
            "trading_date": d.isoformat() + "T00:00:00Z",
            "is_trade_day": is_trade_day,
            "notes": notes,
            "created_at": now,
            "updated_at": now,
        }
        cal.append(new_row)
        _save("market_calendar.json", cal)
        _audit(params_for_log, "ok")
        return {"id": new_row["id"], "trading_date": d.isoformat(), "is_trade_day": is_trade_day, "notes": notes, "created": True}

    row = cal[idx]
    current = row.get("is_trade_day")
    if isinstance(current, str):
        if current.lower() in ("true", "1", "yes"):
            current = True
        elif current.lower() in ("false", "0", "no"):
            current = False

    # Lifecycle transitions allowed: true<->false always allowed.
    row["is_trade_day"] = is_trade_day
    if notes is not None:
        row["notes"] = notes
    row["updated_at"] = _now_iso()
    # Preserve trading_date format but ensure it still matches date.
    td = row.get("trading_date")
    if not (isinstance(td, str) and td[:10] == d.isoformat()):
        row["trading_date"] = d.isoformat() + "T00:00:00Z"

    cal[idx] = row
    _save("market_calendar.json", cal)

    _audit(params_for_log, "ok")
    return {
        "id": row.get("id"),
        "trading_date": d.isoformat(),
        "previous_is_trade_day": current,
        "is_trade_day": is_trade_day,
        "notes": row.get("notes"),
        "created": False,
    }

def list_ingestion_jobs(job_type=None, vendor=None, status=None, created_at_gte=None, created_at_lte=None, dataset_fingerprint=None, page=None, page_size=None, order_by=None, order=None, **_extra):
