            "credential_id": credential_id,
            "status": status_code,
            "error_code": error_code,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": _now_iso(),
        })
        _save(request_log_file, logs)

    def _parse_dt_any(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return None
        ss = s.strip()
        if not ss:
            return None
        try:
            if ss.endswith("Z"):
                return datetime.datetime.fromisoformat(ss[:-1])
            return datetime.datetime.fromisoformat(ss)
        except ValueError:
            return None

    # Defaults
    if page is None:
        page = 1
    if page_size is None:
        page_size = 50
    if order_by is None:
        order_by = "created_at"
    if order is None:
        order = "desc"

    # Validate enums/types
    allowed_job_type_filter = {"snapshot_load", "incremental_update", "backfill", "validation", "rebuild_cache", None}
    if job_type not in allowed_job_type_filter:
        _log(400, None, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "invalid job_type filter", allowed=list(sorted([x for x in allowed_job_type_filter if x is not None])))
    if vendor is not None and not isinstance(vendor, str):
        _log(400, None, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "vendor must be a string or null")
    allowed_status = {"queued", "running", "succeeded", "failed", "cancelled", None}
    if status not in allowed_status:
        _log(400, None, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "invalid status filter", allowed=list(sorted([x for x in allowed_status if x is not None])))
    if dataset_fingerprint is not None and not isinstance(dataset_fingerprint, str):
        _log(400, None, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "dataset_fingerprint must be a string or null")
    if not isinstance(page, int) or page < 1:
        _log(400, None, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "page must be an integer >= 1")
    if not isinstance(page_size, int) or page_size < 1 or page_size > 200:
        _log(400, None, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "page_size must be an integer between 1 and 200")
    if order_by not in {"created_at", "started_at", "finished_at", "status"}:
        _log(400, None, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "invalid order_by")
    if order not in {"asc", "desc"}:
        _log(400, None, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "invalid order")

    gte_dt = None
    lte_dt = None
    if created_at_gte is not None:
        if not isinstance(created_at_gte, str) or _parse_dt_any(created_at_gte) is None:
            _log(400, None, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "created_at_gte must be ISO-8601 timestamp or null")
        gte_dt = _parse_dt_any(created_at_gte)
    if created_at_lte is not None:
        if not isinstance(created_at_lte, str) or _parse_dt_any(created_at_lte) is None:
            _log(400, None, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "created_at_lte must be ISO-8601 timestamp or null")
        lte_dt = _parse_dt_any(created_at_lte)

    jobs = _load("ingestion_jobs.json")

    def _get_dt_field(row, key):
        v = row.get(key)
        if v is None:
            return None
        if isinstance(v, str):
            dt = _parse_dt_any(v)
            return dt
        return None

    # Apply filters
    out = []
    for r in jobs:
        if not isinstance(r, dict):
            continue
        if job_type is not None and r.get("job_type") != job_type:
            continue
        if vendor is not None and r.get("vendor") != vendor:
            continue
        if status is not None and r.get("status") != status:
            continue
        if dataset_fingerprint is not None and r.get("dataset_fingerprint") != dataset_fingerprint:
            continue
        if gte_dt is not None:
            rdt = _get_dt_field(r, "created_at")
            if rdt is None or rdt < gte_dt:
                continue
        if lte_dt is not None:
            rdt = _get_dt_field(r, "created_at")
            if rdt is None or rdt > lte_dt:
                continue
        out.append(r)

    # Sort
    reverse = (order == "desc")

    def _sort_key(r):
        if order_by == "status":
            return (r.get("status") or "")
        dt = _get_dt_field(r, order_by)
        # None sorts last in both orders by mapping to extreme
        if dt is None:
            return datetime.datetime.min if reverse else datetime.datetime.max
        return dt

    try:
        out.sort(key=_sort_key, reverse=reverse)
    except Exception:
        # Avoid raising on mixed types
        _log(500, None, "CONFLICT")
        return _err("CONFLICT", "unable to sort ingestion jobs due to inconsistent data types")

    total = len(out)
    start = (page - 1) * page_size
    end = start + page_size
    items = out[start:end]
    has_more = end < total

    _log(200, None, None)
    return {
        "data": items,
        "meta": {
            "page": page,
            "page_size": page_size,
            "total": total,
            "total_pages": int(math.ceil(total / page_size)) if page_size else 0,
            "has_more": has_more,
            "next_page": (page + 1) if has_more else None,
            "order_by": order_by,
            "order": order,
        },
    }

def create_ingestion_job(job_type, vendor, requested_params, idempotency_key=None, **_extra):
    import json, os, datetime, time, uuid, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0362000" if __import__("os").path.isdir("./environment_mix/0362000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "create_ingestion_job"
    request_log_file = "request_log.json"

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status_code, credential_id=None, error_code=None):
        logs = _load(request_log_file)
        logs.append({
            "id": "req_" + uuid.uuid4().hex,
            "endpoint": endpoint,
            "credential_id": credential_id,
            "status": status_code,
            "error_code": error_code,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": _now_iso(),
        })
        _save(request_log_file, logs)

    # Validate
    allowed_job_type = {"snapshot_load", "incremental_update", "backfill", "validation", "rebuild_cache"}
    if not isinstance(job_type, str) or job_type not in allowed_job_type:
        _log(400, None, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "invalid job_type", allowed=list(sorted(allowed_job_type)))
    if not isinstance(vendor, str) or not vendor.strip():
        _log(400, None, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "vendor must be a non-empty string")
    if not isinstance(requested_params, dict):
        _log(400, None, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "requested_params must be an object")
    if idempotency_key is not None and (not isinstance(idempotency_key, str) or not idempotency_key.strip()):
        _log(400, None, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "idempotency_key must be a non-empty string or null")

    jobs = _load("ingestion_jobs.json")

    # Idempotency support: store mapping in a sidecar collection.
    idem_file = "idempotency_keys.json"
    idem = _load(idem_file)

    # Canonical payload for idempotency matching
    def _canon(obj):
        try:
            return json.dumps(obj, ensure_ascii=False, sort_keys=True, separators=(",", ":"))
        except TypeError:
            # Non-serializable types
            return None

    canon = _canon({"job_type": job_type, "vendor": vendor, "requested_params": requested_params})
    if canon is None:
        _log(400, None, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "requested_params contains non-JSON-serializable values")

    payload_hash = hashlib.sha256(canon.encode("utf-8")).hexdigest()

    if idempotency_key is not None:
        existing_job_id = None
        for r in idem:
            if isinstance(r, dict) and r.get("idempotency_key") == idempotency_key:
                if r.get("payload_hash") != payload_hash:
                    _log(409, None, "CONFLICT")
                    return _err("CONFLICT", "idempotency_key already used with different payload", idempotency_key=idempotency_key)
                existing_job_id = r.get("job_id")
                break
        if existing_job_id is not None:
            for j in jobs:
                if isinstance(j, dict) and j.get("id") == existing_job_id:
                    _log(200, None, None)
                    return {"data": j, "meta": {"idempotent_replay": True}}
            # mapping exists but job missing -> conflict
            _log(409, None, "CONFLICT")
            return _err("CONFLICT", "idempotency record exists but referenced job not found", idempotency_key=idempotency_key)

    now = _now_iso()
    # Server-created job starts queued
    new_job = {
        "id": "job_" + uuid.uuid4().hex,
        "job_type": job_type,
        "vendor": vendor,
        "requested_params": requested_params,
        "dataset_fingerprint": None,
        "row_count": None,
        "started_at": now,
        "finished_at": None,
        "status": "queued",
        "error_message": None,
        "created_at": now,
        "updated_at": now,
    }

    # Enforce unique(job_type, vendor, started_at) by ensuring started_at uniqueness if collision
    existing_started = {(j.get("job_type"), j.get("vendor"), j.get("started_at")) for j in jobs if isinstance(j, dict)}
    if (job_type, vendor, new_job["started_at"]) in existing_started:
        # bump by 1 second until unique (bounded)
        base = datetime.datetime.utcnow().replace(microsecond=0)
        for i in range(1, 10):
            bumped = (base + datetime.timedelta(seconds=i)).isoformat() + "Z"
            if (job_type, vendor, bumped) not in existing_started:
                new_job["started_at"] = bumped
                new_job["created_at"] = bumped
                new_job["updated_at"] = bumped
                break
        if (job_type, vendor, new_job["started_at"]) in existing_started:
            _log(409, None, "CONFLICT")
            return _err("CONFLICT", "could not allocate unique started_at for job")

    jobs.append(new_job)
    _save("ingestion_jobs.json", jobs)

    if idempotency_key is not None:
        idem.append({
            "id": "idem_" + uuid.uuid4().hex,
            "idempotency_key": idempotency_key,
            "payload_hash": payload_hash,
            "job_id": new_job["id"],
            "created_at": now,
        })
        _save(idem_file, idem)

    _log(201, None, None)
    return {"data": new_job, "meta": {"created": 1}}
